   "codice": "extends RefCounted

signal collected(points: int)

var points_got: int = 0
var is_collected: bool = false

func handle_collect(val: int) -> void:
	points_got += val

func run() -> int:
	collected.connect(handle_collect)
	var points: int = 50

	if not is_collected:
		is_collected = true
		collected.emit(points)

	if not is_collected:
		is_collected = true
		collected.emit(points)

	return points_got
",
   "domanda": "Quanto vale `points_got` alla fine?",
   "spiegazione": "La seconda emissione viene bloccata perché `is_collected` è diventato `true` dopo la prima. Il segnale viene emesso una sola volta, quindi `points_got` vale 50."
